import tempfile
import decoy

class Cursor:
    def __init__(self):
        self.resource = tempfile.TemporaryFile(mode='w+t')
        self.close_calls = 0

    def execute(self, sql: str, params: tuple[str, ...]) -> object:
        self.resource.write(params[0])
        return None

    def close(self) -> None:
        self.close_calls += 1
        if self.close_calls == 1:
            raise OSError('synchronous resource-close failure')
        self.resource.close()

made = []
def make():
    cursor = Cursor()
    made.append(cursor)
    return cursor

reproduced = False
try:
    decoy.store(make, ['a'])
except OSError:
    reproduced = bool(made) and made[0].close_calls == 1 and not made[0].resource.closed
finally:
    for cursor in made:
        cursor.close()

print('REPRODUCED' if reproduced else 'NOT REPRODUCED')

